// Normalizar evento de Telegram (mensaje o callback de botón)
const body = $input.first().json.body || $input.first().json;
let chat_id = null;
let text = '';
let is_callback = false;
let callback_data = null;
let user_name = '';

if (body.message) {
  chat_id = body.message.chat.id;
  text = body.message.text || '';
  user_name = body.message.from.first_name || 'Paciente';
} else if (body.callback_query) {
  is_callback = true;
  chat_id = body.callback_query.message.chat.id;
  callback_data = body.callback_query.data;
  text = callback_data;
  user_name = body.callback_query.from.first_name || 'Paciente';
}

return [{
  json: {
    chat_id,
    text,
    user_name,
    is_callback,
    callback_data,
    timestamp: new Date().toISOString()
  }
}];
